# Migrating Flat Pulumi Program to ComponentResource

## Before: Flat Program

```typescript
// index.ts (original flat program)
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";
import * as eks from "@pulumi/eks";

const config = new pulumi.Config();
const environment = config.require("environment"); // "dev" or "prod"

// --- EKS Cluster ---
const cluster = new eks.Cluster("app-cluster", {
    desiredCapacity: environment === "prod" ? 4 : 2,
    minSize: environment === "prod" ? 4 : 2,
    maxSize: environment === "prod" ? 8 : 4,
    instanceType: environment === "prod" ? "t3.large" : "t3.medium",
});

// --- S3 Bucket ---
const bucket = new aws.s3.Bucket("app-assets", {
    versioning: { enabled: true },
    serverSideEncryptionConfiguration: {
        rule: {
            applyServerSideEncryptionByDefault: {
                sseAlgorithm: "AES256",
            },
        },
    },
});

const bucketPublicAccessBlock = new aws.s3.BucketPublicAccessBlock("app-assets-pab", {
    bucket: bucket.id,
    blockPublicAcls: true,
    blockPublicPolicy: true,
    ignorePublicAcls: true,
    restrictPublicBuckets: true,
});

// --- RDS PostgreSQL ---
const dbSubnetGroup = new aws.rds.SubnetGroup("app-db-subnets", {
    subnetIds: cluster.core.vpc.privateSubnetIds,
});

const db = new aws.rds.Instance("app-db", {
    engine: "postgres",
    engineVersion: "15",
    instanceClass: environment === "prod" ? "db.t3.medium" : "db.t3.micro",
    allocatedStorage: 20,
    dbSubnetGroupName: dbSubnetGroup.name,
    multiAz: environment === "prod",
    storageEncrypted: environment === "prod",
    deletionProtection: true,
    backupRetentionPeriod: 7,
    publiclyAccessible: false,
    skipFinalSnapshot: environment !== "prod",
});

// --- IAM ---
const iamUser = new aws.iam.User("app-service-account", {
    tags: { environment },
});

const iamPolicy = new aws.iam.Policy("app-policy", {
    policy: bucket.arn.apply(arn => JSON.stringify({
        Version: "2012-10-17",
        Statement: [{
            Effect: "Allow",
            Action: environment === "prod"
                ? ["s3:GetObject", "s3:PutObject"]
                : ["s3:*"],
            Resource: [arn, `${arn}/*`],
        }],
    })),
});

const iamAttachment = new aws.iam.UserPolicyAttachment("app-policy-attach", {
    user: iamUser.name,
    policyArn: iamPolicy.arn,
});

// --- Secret ---
const dbConnectionString = new pulumi.ConfigSecret("db-connection-string", {
    value: pulumi.interpolate`postgresql://app:${db.password}@${db.endpoint}/appdb`,
});

// --- Exports ---
export const kubeconfig = cluster.kubeconfig;
export const bucketName = bucket.id;
export const dbEndpoint = db.endpoint;
```

## After: ComponentResource with Aliases

```typescript
// appInfrastructure.ts
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";
import * as eks from "@pulumi/eks";

export interface AppInfrastructureArgs {
    environment: pulumi.Input<"dev" | "prod">;
    vpcId?: pulumi.Input<string>;
    privateSubnetIds?: pulumi.Input<pulumi.Input<string>[]>;
}

export class AppInfrastructure extends pulumi.ComponentResource {
    public readonly cluster: eks.Cluster;
    public readonly bucket: aws.s3.Bucket;
    public readonly bucketPublicAccessBlock: aws.s3.BucketPublicAccessBlock;
    public readonly dbSubnetGroup: aws.rds.SubnetGroup;
    public readonly db: aws.rds.Instance;
    public readonly iamUser: aws.iam.User;
    public readonly iamPolicy: aws.iam.Policy;
    public readonly iamAttachment: aws.iam.UserPolicyAttachment;
    public readonly dbConnectionString: pulumi.Output<string>;

    constructor(
        name: string,
        args: AppInfrastructureArgs,
        opts?: pulumi.ComponentResourceOptions,
    ) {
        super("myapp:infra:AppInfrastructure", name, args, opts);

        const isProd = pulumi.output(args.environment).apply(e => e === "prod");

        // ── EKS Cluster ──────────────────────────────────────────────
        this.cluster = new eks.Cluster("app-cluster", {
            desiredCapacity: isProd.apply(p => p ? 4 : 2),
            minSize: isProd.apply(p => p ? 4 : 2),
            maxSize: isProd.apply(p => p ? 8 : 4),
            instanceType: isProd.apply(p => p ? "t3.large" : "t3.medium"),
        }, {
            parent: this,
            aliases: [{ parent: pulumi.rootStackResource }],
        });

        // ── S3 Bucket ────────────────────────────────────────────────
        this.bucket = new aws.s3.Bucket("app-assets", {
            versioning: { enabled: true },
            serverSideEncryptionConfiguration: {
                rule: {
                    applyServerSideEncryptionByDefault: {
                        sseAlgorithm: "AES256",
                    },
                },
            },
        }, {
            parent: this,
            aliases: [{ parent: pulumi.rootStackResource }],
        });

        this.bucketPublicAccessBlock = new aws.s3.BucketPublicAccessBlock("app-assets-pab", {
            bucket: this.bucket.id,
            blockPublicAcls: true,
            blockPublicPolicy: true,
            ignorePublicAcls: true,
            restrictPublicBuckets: true,
        }, {
            parent: this,
            aliases: [{ parent: pulumi.rootStackResource }],
        });

        // ── RDS PostgreSQL ───────────────────────────────────────────
        this.dbSubnetGroup = new aws.rds.SubnetGroup("app-db-subnets", {
            subnetIds: this.cluster.core.vpc.privateSubnetIds,
        }, {
            parent: this,
            aliases: [{ parent: pulumi.rootStackResource }],
        });

        this.db = new aws.rds.Instance("app-db", {
            engine: "postgres",
            engineVersion: "15",
            instanceClass: isProd.apply(p => p ? "db.t3.medium" : "db.t3.micro"),
            allocatedStorage: 20,
            dbSubnetGroupName: this.dbSubnetGroup.name,
            multiAz: isProd,
            storageEncrypted: isProd,
            deletionProtection: true,
            backupRetentionPeriod: 7,
            publiclyAccessible: false,
            skipFinalSnapshot: isProd.apply(p => !p),
        }, {
            parent: this,
            aliases: [{ parent: pulumi.rootStackResource }],
        });

        // ── IAM ──────────────────────────────────────────────────────
        this.iamUser = new aws.iam.User("app-service-account", {
            tags: { environment: args.environment },
        }, {
            parent: this,
            aliases: [{ parent: pulumi.rootStackResource }],
        });

        this.iamPolicy = new aws.iam.Policy("app-policy", {
            policy: pulumi.all([this.bucket.arn, isProd]).apply(([arn, prod]) =>
                JSON.stringify({
                    Version: "2012-10-17",
                    Statement: [{
                        Effect: "Allow",
                        Action: prod
                            ? ["s3:GetObject", "s3:PutObject"]
                            : ["s3:*"],
                        Resource: [arn, `${arn}/*`],
                    }],
                })
            ),
        }, {
            parent: this,
            aliases: [{ parent: pulumi.rootStackResource }],
        });

        this.iamAttachment = new aws.iam.UserPolicyAttachment("app-policy-attach", {
            user: this.iamUser.name,
            policyArn: this.iamPolicy.arn,
        }, {
            parent: this,
            aliases: [{ parent: pulumi.rootStackResource }],
        });

        // ── Secret (Pulumi ConfigSecret) ─────────────────────────────
        this.dbConnectionString = pulumi.interpolate`postgresql://app:${this.db.password}@${this.db.endpoint}/appdb`;

        // Register outputs so Pulumi tracks completion
        this.registerOutputs({
            clusterName: this.cluster.eksCluster.name,
            bucketName: this.bucket.id,
            dbEndpoint: this.db.endpoint,
        });
    }
}
```

```typescript
// index.ts (refactored entry point)
import * as pulumi from "@pulumi/pulumi";
import { AppInfrastructure } from "./appInfrastructure";

const config = new pulumi.Config();
const environment = config.require("environment") as "dev" | "prod";

const infra = new AppInfrastructure("app-infra", {
    environment,
});

export const kubeconfig = infra.cluster.kubeconfig;
export const bucketName = infra.bucket.id;
export const dbEndpoint = infra.db.endpoint;
```

```yaml
# Pulumi.dev.yaml
config:
  myapp:environment: dev
```

```yaml
# Pulumi.prod.yaml
config:
  myapp:environment: prod
```

## How the Aliases Work

The key mechanism is the `aliases` option on every child resource:

```typescript
aliases: [{ parent: pulumi.rootStackResource }]
```

This tells Pulumi: **"This resource previously existed with no explicit parent (i.e., parented to the implicit stack resource)."**

### URN Transformation

| Resource | Before (flat) | After (component) |
|---|---|---|
| Bucket | `urn:pulumi:dev::myapp::aws:s3/bucket:Bucket::app-assets` | `urn:pulumi:dev::myapp::myapp:infra:AppInfrastructure$aws:s3/bucket:Bucket::app-assets` |

Without `aliases`, Pulumi would see the old URN as **deleted** and the new URN as **created** → **replacement**.

With `aliases: [{ parent: pulumi.rootStackResource }]`, Pulumi matches the old URN to the new resource and performs an **in-place adoption** — no destroy/create.

### Verification

```bash
# Preview should show no replacements:
pulumi preview --diff

# Expected output: resources show as "unchanged" or "~ update" (if any
# computed properties shifted), but NEVER "+- replace" or "- delete + create"
```

### Alternative Alias Form

If you need more control (e.g., the resource also changed its `name`), use explicit URN aliases:

```typescript
aliases: [{
    name: "app-assets",
    type: "aws:s3/bucket:Bucket",
    parent: pulumi.rootStackResource,
}]
```

## Checklist

| Step | Detail |
|---|---|
| ✅ Add `parent: this` | Every child resource gets `parent: this` to establish the component hierarchy |
| ✅ Add `aliases` | Every child resource gets `aliases: [{ parent: pulumi.rootStackResource }]` |
| ✅ Keep same `name` | The logical name (first argument) must not change |
| ✅ Keep same `type` | The resource type token must not change |
| ✅ `registerOutputs()` | Call at the end of the component constructor |
| ✅ Verify with `preview` | Confirm zero replacements before deploying |
